  "household.hub.spendMemberNote": "സംയോജിത മൊത്തങ്ങൾ നിങ്ങൾ കാണുന്നു. നിങ്ങൾ വിശദാംശങ്ങൾ പങ്കിടാൻ അനുവദിക്കുന്നില്ലെങ്കിൽ ബില്ലിൻ്റെ പേരുകൾ സ്വകാര്യമായി തുടരും.",
