  "mode.salariedDesc": "ശമ്പളം, EMIs, സബ്‌സ്‌ക്രിപ്‌ഷനുകൾ - ഒറ്റയ്‌ക്കോ കുടുംബത്തിനോ.",
  "guide.appGuide.title": "ആപ്പ് ഗൈഡ്",
  "guide.appGuide.subtitle": "വീട്, സാമ്പത്തിക പൾസ്, ബിൽ എൻട്രി എന്നിവയെ കുറിച്ചുള്ള ഒരു ഹ്രസ്വ വാക്ക്‌ത്രൂ. നിങ്ങൾക്ക് എപ്പോൾ വേണമെങ്കിലും ഘട്ടങ്ങൾ ഒഴിവാക്കാം.",
  "guide.startGuide": "ആപ്പ് ഗൈഡ് ആരംഭിക്കുക",
  "guide.setup.title": "സെറ്റപ്പ് വിസാർഡ്",
  "guide.setup.subtitle": "നിങ്ങൾ Perovo (ശമ്പളമുള്ളതോ വീട്ടുജോലിക്കാരോ) ഉപയോഗിക്കുന്നതെങ്ങനെയെന്ന് അവലോകനം ചെയ്‌ത് വരുമാന അടിസ്ഥാനകാര്യങ്ങൾ അപ്‌ഡേറ്റ് ചെയ്യുക. നിങ്ങളുടെ ബില്ലുകൾ അതേപടി നിലനിൽക്കും.",
  "guide.reviewSetup": "സജ്ജീകരണം അവലോകനം ചെയ്യുക",
  "guide.completedNote": "ഈ ഉപകരണത്തിൽ അവസാന ഗൈഡ് പൂർത്തിയാക്കി. അത് വീണ്ടും കാണാൻ മുകളിൽ ടാപ്പ് ചെയ്യുക.",
  "guide.household.roomsLabel": "മുറികൾ എങ്ങനെ പ്രവർത്തിക്കുന്നു",
  "guide.household.inviteTitle": "നിങ്ങളുടെ കുടുംബ ക്ഷണ കോഡ്",
  "guide.household.inviteText": "കുടുംബാംഗങ്ങളുമായി ഈ 6 പ്രതീക കോഡ് പങ്കിടുക. അവർ Perovo-ലേക്ക് സൈൻ ഇൻ ചെയ്‌ത് Profile-ൽ ഫാമിലി മോഡ് ഓണാക്കി നിങ്ങളുടെ മുറിയിൽ ചേരാൻ ഈ കോഡ് നൽകുക.",
  "guide.household.shareTitle": "നിങ്ങൾ പങ്കിടുന്നത് നിയന്ത്രിക്കുക",
  "guide.household.shareText": "കുടുംബാംഗങ്ങൾ എന്തൊക്കെ കാണണമെന്ന് നിങ്ങൾ തീരുമാനിക്കുക. നിങ്ങളുടെ ദൈനംദിന ചെലവുകൾ മറ്റുള്ളവരെ കാണാൻ അനുവദിക്കുന്നതിന് ഷെയർ ഷെയർ ടോഗിൾ ചെയ്യുക. നിങ്ങളുടെ പ്രതിബദ്ധത ലിസ്റ്റ് പങ്കിടാൻ ബിൽ പേരുകൾ ടോഗിൾ ചെയ്യുക.",
  "guide.household.outlookTitle": "ഗാർഹിക വീക്ഷണം",
  "guide.household.outlookText": "നിങ്ങളുടെ കുടുംബത്തിനുള്ള സംയോജിത സാമ്പത്തിക ആരോഗ്യം - എമർജൻസി ഫണ്ട് കവറേജ്, പങ്കിട്ട സമ്മർദ്ദം, ലക്ഷ്യങ്ങൾ. ഏതെങ്കിലും അംഗത്തിൻ്റെ ഡാറ്റ മാറുമ്പോൾ അപ്ഡേറ്റുകൾ.",
  "guide.pulse.label": "ഇത് എന്താണ്?",
  "guide.pulse.pressureTitle": "പ്രഷർ സ്കോർ",
  "guide.pulse.pressureText": "നിങ്ങളുടെ സാമ്പത്തിക സമ്മർദ്ദ സ്കോർ (0–100) നിങ്ങളുടെ വരുമാനത്തിൻ്റെ എത്രത്തോളം നിശ്ചിത ബാധ്യതകളിലേക്ക് പോകുന്നു എന്ന് കണക്കാക്കുന്നു. 45നു താഴെയുള്ളവർ ആരോഗ്യവാന്മാരാണ്. 70-ന് മുകളിൽ എന്നതിനർത്ഥം നിങ്ങളുടെ ബാധ്യതകൾ ഭാരമുള്ളതാണ് എന്നാണ്.",
  "guide.pulse.freeCashTitle": "Free പണം",
  "guide.pulse.freeCashText": "ഈ മാസം നിങ്ങളുടെ എല്ലാ പ്രതിജ്ഞാബദ്ധമായ പേയ്‌മെൻ്റുകൾക്കും ശേഷം പണം അവശേഷിക്കുന്നു. ഇതാണ് നിങ്ങൾ യഥാർത്ഥത്തിൽ ചെലവഴിക്കുകയോ സംരക്ഷിക്കുകയോ നിക്ഷേപിക്കുകയോ ചെയ്യേണ്ടത്.",
  "guide.pulse.survivalTitle": "അതിജീവന റൺവേ",
  "guide.pulse.survivalText": "ഇന്ന് നിങ്ങൾക്ക് എല്ലാ വരുമാനവും നഷ്ടപ്പെട്ടാൽ, നിങ്ങളുടെ സമ്പാദ്യത്തിൽ നിന്ന് എത്ര മാസത്തെ ബാധ്യതകൾ നികത്താനാകും? 6+ മാസമാണ് ലക്ഷ്യം.",
  "support.title": "സഹായവും പിന്തുണയും",
  "support.subtitle": "മാർഗ്ഗനിർദ്ദേശം, സ്വകാര്യത, ഞങ്ങളിലേക്ക് എത്തിച്ചേരാനുള്ള വഴികൾ.",
  "support.helpCenter": "ആപ്പ് ഗൈഡ് തുറക്കുക",
  "support.helpCenterHint": "വീട്, പൾസ്, ബിൽ എൻട്രി എന്നിവയുടെ വാക്ക്‌ത്രൂ വീണ്ടും പ്ലേ ചെയ്യുക.",
  "support.privacy": "സ്വകാര്യതാ നയം",
  "support.privacyHint": "ഈ ഉപകരണത്തിലെ നിങ്ങളുടെ ഡാറ്റ ഞങ്ങൾ എങ്ങനെ കൈകാര്യം ചെയ്യുന്നു.",
