  "support.contactHint": "അക്കൗണ്ട് അല്ലെങ്കിൽ ഉൽപ്പന്ന ചോദ്യങ്ങൾക്ക് Perovo ഇമെയിൽ ചെയ്യുക.",
  "support.contactEmail": "support@tadsaya.com",
  "support.about": "ഏകദേശം Perovo",
  "support.aboutBody": "Perovo ഇന്ത്യൻ കുടുംബങ്ങളെ ബില്ലുകൾ, വായ്പകൾ, പ്രതിമാസ സമ്മർദ്ദം എന്നിവ ട്രാക്ക് ചെയ്യാൻ സഹായിക്കുന്നു. Perovo-ന് കീഴിലുള്ള SaaS കമ്പനിയായ Perovo നിർമ്മിച്ചത്.",
