  "notifications.enableAlerts": "ബ്രൗസർ അലേർട്ടുകൾ പ്രവർത്തനക്ഷമമാക്കുക",
  "notifications.sendTest": "ടെസ്റ്റ് അയയ്ക്കുക",
  "notifications.markRead": "എല്ലാ അറിയിപ്പുകളും വായിച്ചതായി അടയാളപ്പെടുത്തുക",
  "notifications.unsupported": "നിങ്ങളുടെ ബ്രൗസർ അറിയിപ്പുകളെ പിന്തുണയ്ക്കുന്നില്ല.",
  "notifications.enabledOk": "ബ്രൗസർ അലേർട്ടുകൾ പ്രവർത്തനക്ഷമമാക്കി. ആപ്പ് അടയ്‌ക്കുമ്പോൾ അലേർട്ടുകൾക്കായി ഹോം സ്‌ക്രീനിലേക്ക് ആപ്പ് ചേർക്കുക.",
  "notifications.enableAlertsNative": "അറിയിപ്പുകൾ അനുവദിക്കുക",
  "notifications.enabledOkNative": "അറിയിപ്പുകൾ പ്രവർത്തനക്ഷമമാക്കി. കുടിശ്ശികയും കാലഹരണപ്പെട്ടതുമായ ബില്ലുകൾ ഈ ഉപകരണത്തിൽ നിങ്ങളെ അറിയിക്കും.",
  "notifications.deniedErrNative": "Android ക്രമീകരണങ്ങളിൽ തടഞ്ഞു. ക്രമീകരണങ്ങൾ → ആപ്പുകൾ → പെറോവോ → അറിയിപ്പുകൾ തുറന്ന് അലേർട്ടുകൾ അനുവദിക്കുക, തുടർന്ന് വീണ്ടും ശ്രമിക്കുക.",
  "notifications.testDeniedNative": "അനുമതി നിഷേധിച്ചു. Android ക്രമീകരണങ്ങളിൽ അറിയിപ്പുകൾ അനുവദിക്കുക, തുടർന്ന് വീണ്ടും ശ്രമിക്കുക.",
  "notifications.nativeHint": "ട്രേ അലേർട്ടുകൾ Android അറിയിപ്പുകൾ ഉപയോഗിക്കുന്നു. ഈ സ്‌ക്രീനിൽ ബിൽ റിമൈൻഡറുകൾ ഓണാക്കി വയ്ക്കുക. ആപ്പ് അടച്ചിരിക്കുമ്പോൾ പോലും അടയ്‌ക്കേണ്ടതും കാലഹരണപ്പെട്ടതുമായ ബില്ലുകൾ അറിയിക്കുന്നു.",
  "notifications.deniedErr": "ബ്രൗസർ ക്രമീകരണങ്ങളിൽ തടഞ്ഞു. ഈ സൈറ്റിനായി അറിയിപ്പുകൾ അനുവദിക്കുക, തുടർന്ന് വീണ്ടും ശ്രമിക്കുക.",
  "notifications.testOk": "നിങ്ങളുടെ സിസ്റ്റം അറിയിപ്പ് പാനലിലേക്കും ഇൻ-ആപ്പ് ബെല്ലിലേക്കും അയച്ചു. അത് കാണാൻ ഫോണിൽ താഴേക്ക് സ്വൈപ്പ് ചെയ്യുക.",
  "notifications.testDenied": "അനുമതി നിഷേധിച്ചു. ബ്രൗസറിലോ OS ക്രമീകരണങ്ങളിലോ അലേർട്ടുകൾ പ്രവർത്തനക്ഷമമാക്കുക.",
  "notifications.testUnsupported": "ഈ ബ്രൗസർ അറിയിപ്പുകളെ പിന്തുണയ്ക്കുന്നില്ല.",
