  "notifications.installHint": "ട്രേ അലേർട്ടുകൾക്കായി: ആപ്പ് ഇൻസ്റ്റാൾ ചെയ്യുക (ഹോം സ്‌ക്രീനിലേക്ക് ചേർക്കുക), അറിയിപ്പുകൾ അനുവദിക്കുക, ഓർമ്മപ്പെടുത്തലുകൾ ഓണാക്കി സൂക്ഷിക്കുക. നിങ്ങൾ ആപ്പ് വിടുമ്പോഴോ ഏതാനും മണിക്കൂറുകൾ കൂടുമ്പോഴോ (Android/Chrome) അടയ്‌ക്കേണ്ടതും കാലഹരണപ്പെട്ടതുമായ ബില്ലുകൾ അറിയിക്കുന്നു. iPhone ന് ഹോം സ്‌ക്രീൻ ആപ്പ് ഐക്കൺ ആവശ്യമാണ് - Safari ടാബുകൾക്ക് മാത്രം പശ്ചാത്തലം അറിയിക്കാൻ കഴിയില്ല.",
