  "add.guidanceRollForward": "നിങ്ങൾ ഒരു സൈക്കിൾ മായ്ച്ചതിന് ശേഷം പ്രതിമാസ, വാർഷിക ഇനങ്ങൾ മുന്നോട്ട് പോകും",
  "add.form.startDateHint": "(അത് തുടങ്ങിയപ്പോൾ)",
  "add.form.endDateCancelHint": "(optional — cancel rEMInder)",
  "add.form.endDateOptional": "(ഓപ്ഷണൽ)",
  "add.form.dueDateHint": "അടുത്ത പേയ്‌മെൻ്റ് തീയതി (ആരംഭിച്ചതിന് സമാനമല്ല). നിങ്ങളുടെ ആരംഭ ദിവസം മുതലുള്ള അടുത്ത തുക ഞങ്ങൾ നിർദ്ദേശിക്കുകയും ആവർത്തിക്കുകയും ചെയ്യുന്നു.",
  "add.form.priorSpendHint": "Est. ~₹{amount} paid in years before {year} — included in spend totals. RecoRD payments this year as you go.",
  "add.form.chitInstallmentHint": "ചിട്ടി മൂല്യത്തിൽ നിന്നും മാസത്തിൽ നിന്നും. നിങ്ങളുടെ ഗ്രൂപ്പ് മറ്റൊരു നമ്പറാണ് ഉപയോഗിക്കുന്നതെങ്കിൽ ചിട്ടി വിശദാംശങ്ങളിൽ \"നിശ്ചിത തുക\" ഉപയോഗിക്കുക.",
  "add.form.chitRepeatNote": "ചിട്ടി അവസാനിക്കുന്നത് വരെ പ്രതിമാസം ആവർത്തിക്കുന്നു. ഒരു പുതിയ മാസം ആരംഭിക്കുമ്പോൾ, നിങ്ങളുടെ കുടിശ്ശിക തുക കുറഞ്ഞ ഇൻസ്‌റ്റാൾമെൻ്റിലേക്ക് അപ്‌ഡേറ്റ് ചെയ്യും - നിങ്ങൾ അത് സ്വയം മാറ്റരുത്.",
  "add.form.priorityHint": "മറ്റ് ബില്ലുകൾക്ക്, അടിയന്തര സാഹചര്യങ്ങൾക്കനുസരിച്ച് മുൻഗണന നൽകുക.",
  "add.form.priorityAuto": "{category} ബില്ലുകൾക്ക് സ്വയമേവ മുൻഗണന സജ്ജമാക്കി.",
