  "privacy.effective": "പ്രാബല്യത്തിൽ: 2026 ജൂൺ",
  "privacy.collectTitle": "ഞങ്ങൾ എന്താണ് ശേഖരിക്കുന്നത്",
  "privacy.collectBody": "പേര്, ഇമെയിൽ, മൊബൈൽ നമ്പർ, പ്രതിമാസ വരുമാനം, PAN (ഓപ്ഷണൽ), സാമ്പത്തിക പ്രതിബദ്ധതകൾ, വായ്പാ രേഖകൾ, പ്രതിമാസ സ്നാപ്പ്ഷോട്ടുകൾ എന്നിവ പ്രദർശിപ്പിക്കുക.",
  "privacy.whyTitle": "എന്തുകൊണ്ടാണ് ഞങ്ങൾ അത് ശേഖരിക്കുന്നത്",
  "privacy.whyBody": "നിങ്ങളുടെ സാമ്പത്തിക സമ്മർദ്ദ സ്കോർ, പ്രതിബദ്ധത ഭാരം, അതിജീവന റൺവേ, വായ്പാ രേഖകൾ എന്നിവ കണക്കാക്കാൻ മാത്രം. മറ്റൊരു ഉദ്ദേശവുമില്ല.",
  "privacy.whereTitle": "എവിടെയാണ് സംഭരിച്ചിരിക്കുന്നത്",
  "privacy.whereBody": "പ്രാഥമികമായി നിങ്ങളുടെ ഉപകരണത്തിൽ (ലോക്കൽ സ്റ്റോറേജ്). ക്ലൗഡ് സമന്വയം പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ ഓപ്ഷണലായി Supabase എന്നതിൽ (വിശ്രമവേളയിൽ എൻക്രിപ്റ്റ് ചെയ്‌തിരിക്കുന്നു, ഓരോ ഉപയോക്താവിനും ഒറ്റപ്പെട്ടതാണ്).",
  "privacy.notTitle": "ഞങ്ങൾ എന്താണ് ചെയ്യാത്തത്",
  "privacy.notBody": "ഞങ്ങൾ നിങ്ങളുടെ ഡാറ്റ വിൽക്കില്ല. ഞങ്ങൾ ക്രെഡിറ്റ് ബ്യൂറോകളുമായി പങ്കിടില്ല. ഞങ്ങൾ പരസ്യത്തിനായി ഡാറ്റ ഉപയോഗിക്കുന്നില്ല. Razorpay പേയ്‌മെൻ്റുകൾ കൈകാര്യം ചെയ്യുന്നു - Perovo ഒരിക്കലും നിങ്ങളുടെ കാർഡ് വിശദാംശങ്ങൾ കാണില്ല.",
  "privacy.rightsTitle": "നിങ്ങളുടെ അവകാശങ്ങൾ (DPDP നിയമം 2023)",
  "privacy.rightsAccess": "ആക്സസ്: Profile → ഡാറ്റ എക്സ്പോർട്ട് ചെയ്യുക",
  "privacy.rightsCorrection": "തിരുത്തൽ: ആപ്പിൽ നേരിട്ട് എഡിറ്റ് ചെയ്യുക",
  "privacy.rightsErasure": "മായ്ക്കൽ: Profile → എല്ലാ ഡാറ്റയും ഇല്ലാതാക്കുക",
