  "sync.autoBullet": "നിങ്ങൾ എഡിറ്റ് ചെയ്‌തതിന് ശേഷം (പ്രാപ്‌തമാക്കുമ്പോൾ) സ്വയമേവയുള്ള ബാക്കപ്പ് പ്രവർത്തിക്കുന്നു.",
  "sync.title": "അക്കൗണ്ട് ബാക്കപ്പ്",
  "sync.notConfigured": "Supabase കോൺഫിഗർ ചെയ്തിട്ടില്ല. VITE_SUPABASE_URL, VITE_SUPABASE_ANON_KEY എന്നിവ ചേർക്കുക, തുടർന്ന് supabase/migrations/ എന്നതിൽ മൈഗ്രേഷനുകൾ റൺ ചെയ്യുക.",
  "sync.freePlanBody": "Free പ്ലാൻ ഈ ഉപകരണത്തിൽ മാത്രം ഡാറ്റ സൂക്ഷിക്കുന്നു. നിങ്ങളുടെ അക്കൗണ്ടിന് കീഴിൽ ഒരു സ്വകാര്യ Supabase ബാക്കപ്പ് സംരക്ഷിക്കുന്നതിന് Pro അല്ലെങ്കിൽ Power ലേക്ക് അപ്‌ഗ്രേഡ് ചെയ്യുക (എപ്പോൾ വേണമെങ്കിലും പ്രവർത്തനക്ഷമമാക്കുക അല്ലെങ്കിൽ പ്രവർത്തനരഹിതമാക്കുക).",
  "sync.freePlanHint": "നിങ്ങൾക്ക് തുടർന്നും JSON ഫയലുകൾ കയറ്റുമതി ചെയ്യാനും ഇറക്കുമതി ചെയ്യാനും കഴിയും.",
  "sync.signInBody": "നിങ്ങളുടെ പ്ലാനിൽ Supabase ബാക്കപ്പ് ഉൾപ്പെടുന്നു. അക്കൗണ്ടിന് കീഴിൽ സൈൻ ഇൻ ചെയ്യുക, തുടർന്ന് ഈ ഉപകരണത്തിൻ്റെ ഡാറ്റ {account} എന്നതിന് കീഴിൽ സംരക്ഷിക്കാൻ ബാക്കപ്പ് ഓണാക്കുക.",
  "sync.signInHint": "നിങ്ങൾ പുനഃസ്ഥാപിക്കാൻ തിരഞ്ഞെടുക്കുന്നതുവരെ പ്രാദേശിക ഡാറ്റ ഉപകരണത്തിൽ നിലനിൽക്കും.",
  "sync.accountLine": "അക്കൗണ്ട്: {account} — Supabase (RLS) ലെ ഒരു സ്വകാര്യ വരി. പ്രാദേശിക സംഭരണം പ്രാഥമികമായി തുടരുന്നു.",
