  "stability.headline.dualIncome": "ഗാർഹിക വരുമാനം സംയോജിതമായി ഉപയോഗിക്കുന്നു - ഏതെങ്കിലും സ്രോതസ്സ് നഷ്ടപ്പെടുന്നത് സമ്മർദ്ദം വർദ്ധിപ്പിക്കും.",
