  "stability.goalBalance.stagger": "ഒന്നിലധികം ലക്ഷ്യങ്ങൾ സജീവമാണ് - അമ്പരപ്പിക്കുന്ന ലക്ഷ്യങ്ങൾ, അതിനാൽ ഒരു നാഴികക്കല്ല് മറ്റുള്ളവയുടെ പുരോഗതി കുറയ്ക്കില്ല.",
  "insight.family-heavy-month": "{month} ഉയർന്ന മർദ്ദമായിരിക്കാം (~{amount}{categories}).",
  "insight.household-payer-split": "പണമടയ്ക്കുന്നയാളുടെ ബില്ലുകൾ (ഏകദേശം തുറന്ന തുകകൾ): {summary}.",
  "insight.lifestyle-inflation": "ആവർത്തിച്ചുള്ള പേയ്‌മെൻ്റുകൾ ചരിത്രത്തിൻ്റെ {months} മാസത്തിൽ ഉടനീളം {percent}% വർദ്ധിച്ചു.",
  "insight.subscription-growth": "സബ്‌സ്‌ക്രിപ്‌ഷൻ ചെലവ് വർദ്ധിച്ചേക്കാം - പുതുക്കലുകളും ഡ്യൂപ്ലിക്കേറ്റുകളും അവലോകനം ചെയ്യുക.",
  "insight.family-burden": "ഗാർഹിക ബില്ലുകൾ വരുമാനത്തിൻ്റെ വലിയൊരു പങ്ക് ഉപയോഗിക്കുന്നു - പങ്കിട്ട പ്രതിബദ്ധതകൾ ഒരുമിച്ച് അവലോകനം ചെയ്യുക.",
  "insight.family-dependency": "വീട് കർശനമായ വരുമാന-ബില്ലുകളുടെ അനുപാതത്തെ ആശ്രയിച്ചിരിക്കുന്നു - അടിയന്തര ആസൂത്രണം എല്ലാവർക്കും പ്രധാനമാണ്.",
  "insight.family-school": "സ്‌കൂൾ ഫീസ് ഏകദേശം {amount} വീട്ടുപകരണങ്ങൾ തുറക്കാൻ ചേർക്കുന്നു.",
  "insight.family-renewals": "{count} വലിയ വാർഷിക അല്ലെങ്കിൽ ഇൻഷുറൻസ് ബില്ലുകൾ വരുന്നു — ആ മാസങ്ങളിൽ പണം പ്ലാൻ ചെയ്യുക.",
  "insight.family-income-concentration": "ഒരു വരുമാനം നിലവിൽ കുടുംബ സമ്മർദ്ദത്തിൻ്റെ {pct}% പിന്തുണയ്ക്കുന്നു - നിങ്ങൾക്ക് കഴിയുന്നിടത്ത് അപകടസാധ്യത വ്യാപിപ്പിക്കുക.",
  "insight.family-dependency-burden": "{count} ആളുകൾ ഈ കുടുംബത്തെ ആശ്രയിക്കുന്നു - അടിയന്തര ആസൂത്രണം എല്ലാവരേയും സംരക്ഷിക്കുന്നു.",
  "insight.family-single-earner-risk": "ഒരൊറ്റ വരുമാനക്കാരൻ {dependents} ആശ്രിതരെ (കൾ) പിന്തുണയ്ക്കുന്നു - വരുമാന ആഘാതങ്ങൾക്കുള്ള ബഫർ നിർമ്മിക്കുക.",
  "insight.family-forecast-pressure-rise": "അടുത്ത മാസം ഗാർഹിക സമ്മർദ്ദം ഉയർന്നേക്കാം (മർദ്ദം +{delta} പോയിൻ്റ്).",
  "insight.family-forecast-low-liquidity": "ലിക്വിഡിറ്റി {month} ചുറ്റുപാടും മുറുകിയേക്കാം - കനത്ത ബില്ലുകൾ ഇറങ്ങുന്നതിന് മുമ്പ് പണം പ്ലാൻ ചെയ്യുക.",
  "insight.family-forecast-emergency-weak": "അടിയന്തര പ്രതിരോധശേഷി ലക്ഷ്യത്തിൻ്റെ {pct}% ആണ് - വീടിന് അനുയോജ്യമായതിനേക്കാൾ കുറഞ്ഞ തലയണയാണുള്ളത്.",
  "insight.family-forecast-school-window": "സ്കൂൾ ഫീസ് പ്രഷർ ക്ലസ്റ്ററുകൾ ഏകദേശം {month} (~{amount} അടയ്‌ക്കേണ്ടതുണ്ട്).",
  "insight.family-contribution-primary": "പ്രാഥമിക വരുമാനം {months} മാസത്തിലുടനീളം {categories} വഹിച്ചു - ഏകദേശം {amount} രേഖപ്പെടുത്തി.",
  "insight.family-contribution-secondary": "രണ്ടാമത്തെ വരുമാനം {months} മാസത്തേക്ക് {categories} സഹായിച്ചു - ഏകദേശം {amount} രേഖപ്പെടുത്തി.",
  "insight.family-contribution-shared": "പങ്കിട്ട സംഭാവനകൾ {months} മാസത്തേക്ക് {categories} ഉൾക്കൊള്ളുന്നു — ഏകദേശം {amount} രേഖപ്പെടുത്തി.",
  "insight.family-contribution-survived-pressure": "ഈ കുടുംബം ഒരു ഇറുകിയ കാലയളവിലൂടെ നീങ്ങി ({months} വെല്ലുവിളി നിറഞ്ഞ മാസങ്ങൾ, {period} ഉൾപ്പെടെ).",
  "insight.heavy-month": "{month} ന് ഉയർന്ന ബാധ്യതകളുണ്ട് (~{amount} ബാധ്യത).",
  "insight.light-month": "{month} ന് ഏറ്റവും കൂടുതൽ മുറിയുണ്ട് (കുടിശ്ശിക കഴിഞ്ഞ് ~{amount} സൗജന്യം).",
  "insight.goal-capacity": "{name} ആവശ്യമുണ്ട് ~{amount}/മാസം — നിലവിലുള്ള സൗജന്യ പണത്തെ കവിയുന്നു.",
  "insight.education-timeline": "{name}: ലക്ഷ്യത്തിലെത്താൻ ~{months} മാസത്തേക്ക് ~{amount}/മാസം.",
  "insight.dual-income": "ഗാർഹിക വരുമാനം സംയോജിതമായി ഉപയോഗിക്കുന്നു - ഏതെങ്കിലും സ്രോതസ്സ് നഷ്ടപ്പെടുന്നത് സമ്മർദ്ദം വർദ്ധിപ്പിക്കും.",
  "insight.stress-contributors": "ഉയർന്ന മർദ്ദം ഉറവിടങ്ങൾ: {names}.",
  "insight.goal-overlap": "പ്രതിമാസ കുടിശ്ശിക വരുമാനത്തിൻ്റെ വലിയൊരു പങ്ക് ഉപയോഗിക്കുമ്പോൾ നിങ്ങൾ {count} ലക്ഷ്യങ്ങൾ ട്രാക്ക് ചെയ്യുന്നു - എല്ലാ മേഖലകളിലും പുരോഗതി മന്ദഗതിയിലായിരിക്കാം.",
  "insight.goal-edu-wedding": "വിദ്യാഭ്യാസത്തിനും വിവാഹത്തിനും അല്ലെങ്കിൽ ഇവൻ്റ് ലക്ഷ്യങ്ങൾക്കും ഒരു വ്യക്തമായ പ്രതിമാസ സ്ലൈസ് ആവശ്യമാണ് - ഏതാണ് ആദ്യം വരുന്നതെന്ന് പരിഗണിക്കുക.",
  "insight.goal-debt-save": "പരിമിതമായ സൗജന്യ പണത്തിൽ ഒരേസമയം കടം വീട്ടുന്നതും സമ്പാദ്യം കെട്ടിപ്പടുക്കുന്നതും ബുദ്ധിമുട്ടാണ് - ഒരു ലക്ഷ്യത്തിന് മുൻഗണന നൽകുക.",
