  "profileHub.scoreWhy.runway.what": "വരുമാനം താൽക്കാലികമായി നിർത്തിയാൽ മാസങ്ങൾ നിങ്ങൾക്ക് അവശ്യവസ്തുക്കൾ പരിരക്ഷിക്കാം (ദ്രാവക സമ്പാദ്യം + സൗജന്യ പണം).",
