  "profileHub.scoreWhy.flexibility.low": "ഭൂരിഭാഗം വരുമാനവും ആവർത്തിച്ചുള്ള ബില്ലുകൾക്ക് ഇതിനകം പ്രതിജ്ഞാബദ്ധമാണ്.",
  "profileHub.scoreWhy.flexibility.ok": "നിങ്ങൾ ഓരോ മാസവും അർത്ഥവത്തായ സൗജന്യ പണം നിലനിർത്തുന്നു.",
  "profileHub.scoreWhy.debt.what": "പ്രതിമാസ വരുമാനത്തിൻ്റെ ഒരു വിഹിതമായി EMI കൂടാതെ ലോൺ പേയ്‌മെൻ്റുകളും.",
