  "profileHub.scoreWhy.lending.empty": "ഇതുവരെ വായ്പാ എൻട്രികളൊന്നുമില്ല - ഈ സ്കോർ നിർമ്മിക്കുന്നതിന് ഡീലുകളും ലോഗ് തിരിച്ചടവുകളും ചേർക്കുക.",
